import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Sound of a recording alert of the kit recorder (LiDAR silent, clock
/// unlocked, SSD error …). Distinct from the "dur-çek-yürü" beep.
abstract interface class AlertSound {
  Future<void> play();
}

/// Plays `assets/sounds/alert.wav` (0.4 s at 880 Hz, generated by
/// `tool/alert_sound.dart`) with a vibration. Errors are logged, never
/// thrown: a missing sound must not stop the recording.
class AssetAlertSound implements AlertSound {
  AssetAlertSound();

  /// Relative to `assets/` (audioplayers' default prefix).
  static const asset = 'sounds/alert.wav';

  AudioPlayer? _player;

  @override
  Future<void> play() async {
    try {
      final player = _player ??= AudioPlayer();
      await player.stop();
      await player.play(AssetSource(asset));
    } catch (e) {
      debugPrint('alert sound: $e');
    }
    try {
      await HapticFeedback.heavyImpact();
    } catch (_) {}
  }
}

/// Counts plays instead of sounding (tests).
class FakeAlertSound implements AlertSound {
  int count = 0;

  @override
  Future<void> play() async => count++;
}
